-- UNEXECUTED READ-ONLY POSTFLIGHT. One deterministic catalog result.
WITH t AS (SELECT 'public.legal_policy_acceptances'::regclass AS oid),
facts AS (SELECT (SELECT count(*) FROM pg_attribute WHERE attrelid=(SELECT oid FROM t) AND attnum>0 AND NOT attisdropped)=14 AS columns_exact,(SELECT count(*) FROM pg_constraint WHERE conrelid=(SELECT oid FROM t))=12 AS constraints_exact,(SELECT count(*) FROM pg_index WHERE indrelid=(SELECT oid FROM t))=3 AS indexes_exact,(SELECT relrowsecurity AND NOT relforcerowsecurity FROM pg_class WHERE oid=(SELECT oid FROM t)) AS rls_exact,(SELECT count(*) FROM pg_policy WHERE polrelid=(SELECT oid FROM t) AND polname='legal_policy_acceptances_select_own' AND polcmd='r')=1 AS policy_exact,(SELECT count(*) FROM pg_trigger WHERE tgrelid=(SELECT oid FROM t) AND tgname='trg_legal_policy_acceptances_set_updated_at' AND NOT tgisinternal)=1 AS trigger_exact,(SELECT count(*) FROM pg_proc WHERE oid=to_regprocedure('public.record_current_legal_policy_acceptance(uuid,text,text,text,text,smallint,text)'))=1 AS rpc_exact,(SELECT pg_get_userbyid(p.proowner)='postgres' AND p.prosecdef AND p.provolatile='v' AND p.proparallel='u' AND p.proconfig=ARRAY['search_path=public, pg_temp'] FROM pg_proc p WHERE p.oid=to_regprocedure('public.record_current_legal_policy_acceptance(uuid,text,text,text,text,smallint,text)')) AS rpc_metadata_exact,NOT EXISTS (SELECT 1 FROM pg_proc f CROSS JOIN LATERAL aclexplode(coalesce(f.proacl,acldefault('f',f.proowner))) a WHERE f.oid=to_regprocedure('public.record_current_legal_policy_acceptance(uuid,text,text,text,text,smallint,text)') AND a.grantee=0 AND a.privilege_type='EXECUTE') AND NOT has_function_privilege('anon','public.record_current_legal_policy_acceptance(uuid,text,text,text,text,smallint,text)','EXECUTE') AND NOT has_function_privilege('authenticated','public.record_current_legal_policy_acceptance(uuid,text,text,text,text,smallint,text)','EXECUTE') AND has_function_privilege('service_role','public.record_current_legal_policy_acceptance(uuid,text,text,text,text,smallint,text)','EXECUTE') AS rpc_acl_exact,has_table_privilege('authenticated',(SELECT oid FROM t),'SELECT') AS table_acl_exact,NOT EXISTS (SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260712') AS ledger_unchanged)
SELECT jsonb_build_object('packet_version','legal-consent-forward-only-postflight-v1','classification',CASE WHEN columns_exact AND constraints_exact AND indexes_exact AND rls_exact AND policy_exact AND trigger_exact AND rpc_exact AND rpc_metadata_exact AND rpc_acl_exact AND table_acl_exact AND ledger_unchanged THEN 'LEGAL_CONSENT_CATALOG_EXACT' ELSE 'LEGAL_CONSENT_CATALOG_INCOMPLETE' END,'expected_object_count',52,'facts',to_jsonb(facts)) AS packet FROM facts;
